"""Small self-contained HTML UI for the language reviewer."""

HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Mulu Agent Language Reviewer</title>
<style>
:root{--ink:#17202a;--muted:#607080;--brand:#2457d6;--soft:#eef3ff;--line:#dbe3ee;--warn:#a05a00}*{box-sizing:border-box}body{margin:0;font-family:Inter,system-ui,sans-serif;color:var(--ink);background:#f7f9fc}header{background:linear-gradient(120deg,#172e67,#2457d6);color:#fff;padding:42px 24px 70px}.wrap{max-width:1080px;margin:auto}.eyebrow{letter-spacing:.12em;text-transform:uppercase;font-weight:700;font-size:.75rem;opacity:.8}h1{font-size:clamp(2rem,4vw,3.8rem);line-height:1.04;max-width:760px;margin:14px 0}header p{max-width:720px;font-size:1.08rem;opacity:.9}main{margin:-38px auto 50px;position:relative}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:20px}.card{background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 12px 30px #172e6712;padding:24px}label{display:block;font-weight:700;margin-bottom:8px}textarea,select{width:100%;border:1px solid #c9d4e2;border-radius:10px;padding:13px;font:inherit;color:inherit;background:#fff}textarea{min-height:260px;resize:vertical;line-height:1.6}.controls{display:flex;gap:12px;align-items:end;margin-top:16px}.controls>div{flex:1}button{border:0;border-radius:10px;padding:13px 20px;font-weight:800;font:inherit;cursor:pointer;background:var(--brand);color:#fff}button:disabled{opacity:.6;cursor:wait}.sample{color:var(--brand);background:var(--soft);margin-top:12px}.result-head{display:flex;justify-content:space-between;align-items:center;gap:12px;border-bottom:1px solid var(--line);padding-bottom:16px}.score{font-size:2.4rem;font-weight:850;color:var(--brand)}.pill{border-radius:999px;padding:6px 10px;background:var(--soft);color:var(--brand);font-size:.84rem;font-weight:800}.empty{color:var(--muted);line-height:1.7}.summary{background:#f7f9fc;border-radius:10px;padding:14px;margin:18px 0;line-height:1.6}.issue{border-left:4px solid var(--warn);padding:12px 14px;margin:12px 0;background:#fffaf4;border-radius:0 8px 8px 0}.issue strong{display:block;margin-bottom:5px}.issue small{color:var(--muted)}.ok{border-left-color:#147a4b;background:#f3fbf7}@media(max-width:800px){.grid{grid-template-columns:1fr}.controls{flex-direction:column;align-items:stretch}}
</style></head><body><header><div class="wrap"><div class="eyebrow">Mulu Agent</div><h1>Language quality review for East African AI copy.</h1><p>Review Amharic and Afaan Oromo text for clarity, consistency, punctuation, and common machine-generated patterns before it reaches your users.</p></div></header><main class="wrap"><section class="grid"><div class="card"><label for="text">Text to review</label><textarea id="text" placeholder="Paste Amharic or Afaan Oromo text here…"></textarea><div class="controls"><div><label for="language">Language</label><select id="language"><option value="auto">Auto-detect</option><option value="am">Amharic</option><option value="om">Afaan Oromo</option></select></div><button id="review">Review text</button></div><button class="sample" id="sample">Load Afaan Oromo sample</button></div><div class="card" id="output"><div class="empty"><strong>Your review will appear here.</strong><br><br>Suggestions are transparent editorial signals. A fluent speaker should approve production copy.</div></div></section></main>
<script>const text=document.querySelector('#text'),language=document.querySelector('#language'),output=document.querySelector('#output'),review=document.querySelector('#review');document.querySelector('#sample').onclick=()=>{text.value='Akkam jirtu? Tajaajila keenya fayyadamuuf galatoomi.';language.value='om'};review.onclick=async()=>{if(!text.value.trim()){output.innerHTML='<div class="empty">Add text first, then choose <strong>Review text</strong>.</div>';return}review.disabled=true;review.textContent='Reviewing…';try{const r=await fetch('/api/language/review',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:text.value,language:language.value})}),d=await r.json();if(!r.ok)throw Error(d.detail||'Review failed');const issues=d.issues.length?d.issues.map(i=>`<div class="issue"><strong>${esc(i.title)}</strong><div>${esc(i.message)}</div><small>${esc(i.suggestion)}</small></div>`).join(''):'<div class="issue ok"><strong>No automatic issues found</strong><div>Still ask a fluent reviewer to confirm meaning, tone, and cultural fit.</div></div>';output.innerHTML=`<div class="result-head"><div><span class="pill">${esc(d.language_name)}</span><div class="score">${d.score}/100</div></div><span>${d.word_count} words · ${d.character_count} characters</span></div><div class="summary">${esc(d.summary)}</div><h3>Suggestions</h3>${issues}`}catch(e){output.innerHTML=`<div class="empty">Could not complete the review: ${esc(e.message)}</div>`}review.disabled=false;review.textContent='Review text'};function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}</script></body></html>'''
